mkdir -p logs/acpr_scaling_20260706/perf logs/acpr_scaling_20260706/resource
echo "Continue submitting remaining ACPR scaling jobs at $(date)" | tee -a "$SUBMIT_LOG"

SBATCH_S1_N2='sbatch -w g[0013,0032,0045,0048,0030,0042,0066,0053] -N 2 -p gpu --gres=gpu:1 --qos=gpugpu'
SBATCH_S1_N4='sbatch -w g[0013,0032,0045,0048,0030,0042,0066,0053] -N 4 -p gpu --gres=gpu:1 --qos=gpugpu'
