SBATCH_S4_N2='sbatch -w g[0013,0032,0045,0048,0030,0042,0066,0053] -N 2 -p gpu --gres=gpu:4 --qos=gpugpu'
SBATCH_S4_N4='sbatch -w g[0013,0032,0045,0048,0030,0042,0066,0053] -N 4 -p gpu --gres=gpu:4 --qos=gpugpu'
SBATCH_S4_N8='sbatch -w g[0013,0032,0045,0048,0030,0042,0066,0053] -N 8 -p gpu --gres=gpu:4 --qos=gpugpu'

submit_cmd() {
  local cmd="$1"
  echo "----" | tee -a "$SUBMIT_LOG"
  echo "$cmd" | tee -a "$SUBMIT_LOG"
  eval "$cmd" 2>&1 | tee -a "$SUBMIT_LOG"
  local rc=${PIPESTATUS[0]}
  if [ "$rc" -ne 0 ]; then
    echo "FAILED rc=$rc: $cmd" | tee -a "$SUBMIT_LOG"
  fi
}

submit_cmd 'nworkers=8 bs=64 dnn=bert_base senlen=64 compressor=none overlap_profile=0 loss_log_every=0 num_warmup_batches=500 num_batches_per_iter=10 num_iters=100 $SBATCH_S1_N8 --job-name=S1N8_P0_dense --output=logs/acpr_scaling_20260706/perf/S1N8_P0_dense_%j.out horovod_mpi_cj.sh'
submit_cmd 'nworkers=8 bs=64 dnn=bert_base senlen=64 compressor=halfrankk compress_rank=16 compress_warmup=300 compress_refresh_k=0 rank_schedule=fixed active_prefix_enabled=1 embedding_policy=word overlap_profile=0 loss_log_every=0 num_warmup_batches=500 num_batches_per_iter=10 num_iters=100 $SBATCH_S1_N8 --job-name=S1N8_P1_fixed_rank --output=logs/acpr_scaling_20260706/perf/S1N8_P1_fixed_rank_%j.out horovod_mpi_cj.sh'
